VALUES (NULL, 'tic-report-v1', '江西中标检检测报告（首套版式）', 1, 'active', $config${"templateKey":"tic-report-v1","name":"江西中标检检测报告（首套版式）","institution":"江西中标检检测中心有限公司","layoutMarkers":["检测报告","报告编号","检验结论","检测项目"],"fields":{"reportNumber":{"labels":["报告编号"],"pattern":"报告编号\\s*[:：]?\\s*([A-Za-z0-9-]{6,40})","required":true,"format":"^[A-Z]{2,6}-[0-9]{6}-[0-9]{3}$","exclude":["分包"]},"productName":{"labels":["产品名称"],"pattern":"产品名称\\s*[:：]?\\s*([^\\n]+)","required":true},"institution":{"labels":["检测机构"],"pattern":"检测机构\\s*[:：]?\\s*([^\\n]+)","required":true,"exclude":["分包"]},"clientUnit":{"labels":["委托单位"],"pattern":"委托单位\\s*[:：]?\\s*([^\\n]+)","required":true},"inspectedUnit":{"labels":["受检单位"],"pattern":"受检单位\\s*[:：]?\\s*([^\\n]+)"},"manufacturer":{"labels":["生产单位"],"pattern":"生产单位\\s*[:：]?\\s*([^\\n]+)"},"model":{"labels":["型号"],"pattern":"(?:型号|规格型号)\\s*[:：]?\\s*([^\\n]+)"},"category":{"labels":["检验类别","检测类别"],"pattern":"(?:检验|检测)类别\\s*[:：]?\\s*([^\\n]+)"},"basis":{"labels":["检验依据","检测依据"],"pattern":"(?:检验|检测)依据\\s*[:：]?\\s*([^\\n]+)"},"reportDate":{"labels":["报告日期"],"pattern":"报告日期\\s*[:：]?\\s*([0-9]{4}\\s*[-年/.]\\s*[0-9]{1,2}\\s*[-月/.]\\s*[0-9]{1,2}\\s*日?)","required":true,"format":"date","exclude":["抽样","送检","上传","创建","打印"]},"conclusion":{"labels":["检验结论","检测结论"],"pattern":"(?:检验|检测)结论\\s*[:：]?\\s*([^\\n]+)","required":true},"remark":{"labels":["备注"],"pattern":"备注\\s*[:：]?\\s*([^\\n]+)"}},"details":{"startMarkers":["检测项目"],"endMarkers":["备注","以下空白"],"skipPatterns":["序号","技术要求\\s+单位","第\\s*[0-9]+\\s*页","共\\s*[0-9]+\\s*页"],"sectionPattern":"^(?P<section>[一二三四五六七八九十]+、[^\\s].*)$","rowPattern":"^(?:[0-9]+[.、]?\\s*)?(?P<item>.+?)\\s+(?P<requirement>[≤≥<>＜＞]?\\s*[0-9]+(?:\\.[0-9]+)?(?:\\s*[~～-]\\s*[0-9.]+)?|不得检出|/)\\s*(?P<unit>%|mg/kg|g/kg|mg/L|g/L|mm|MPa|N|℃|h|min|/)?\\s*(?P<method>(?:GB|HJ|ISO|ASTM|EN|QB|JC)[^\\s]*\\s*[0-9-]*)?\\s*(?P<result>未检出(?:[（(][^）)]*[）)])?|[0-9]+(?:\\.[0-9]+)?)\\s*(?P<judgement>合格|不合格|/)$","continuationPattern":"^\\s{2,}(?P<continuation>.+)$","minRows":1,"expectedRows":34,"requireFields":["item","requirement","result","judgement"]},"validation":{"requiredFields":["reportNumber","productName","institution","clientUnit","reportDate","conclusion"],"requireDetails":true,"allowEmptyValues":["/","—","-","无"]}}$config$::jsonb, 'platform:system', now());
